const errors={account_active:['This account is already searching in another tab. Cancel that search there, or wait a few seconds after closing it.',''],username_reserved:['That username is reserved. Choose another name, or sign in to the account that owns it.','Escolhe outro nome.'],rate_limited:['Too many requests. Wait one minute and try again.','Demasiados pedidos. Aguarda um minuto e tenta novamente.'],opponent_left:['Your opponent left. Choose a new game.','O adversário saiu. Escolhe outro jogo.'],stale_match:['The match changed. Check the current game and try again.','A partida mudou. Verifica o jogo atual e tenta novamente.'],five_letters:['Enter a five-letter word.','Escreve uma palavra com cinco letras.'],unknown_word:['Not in this preview’s dictionary. Try another word.','Não está no dicionário desta versão. Experimenta outra palavra.'],repeated:['That word is already on your board.','Essa palavra já está no teu tabuleiro.'],locked:['Your guess is locked. Wait for the reveal.','A tua tentativa está confirmada. Aguarda a revelação.'],not_turn:['It’s your partner’s turn.','É a vez do teu parceiro.'],room_full:['This room already has two players or has started.','Esta sala já tem dois jogadores ou já começou.'],room_expired:['Room not found or expired. Check the code or create a new room.','Sala não encontrada ou expirada. Verifica o código ou cria outra sala.'],room_access:['Join using the room code to take a player seat.','Entra com o código da sala para ocupar um lugar.'],session:['The browser session could not be restored. Rejoin the room.','Não foi possível restaurar a sessão. Volta a entrar na sala.'],busy:['The room changed at the same time. Please try again.','A sala foi alterada ao mesmo tempo. Tenta novamente.'],not_playing:['This match is no longer in progress.','Esta partida já não está em curso.'],not_waiting:['The match has already started.','A partida já começou.'],sign_in_required:['Sign in to play Competitive. Normal games are open to everyone.',''],online_duel_only:['The public queue is Duel only. Choose Friends for Race, Co-op or Word swap.',''],storage_unavailable:['Room service is temporarily unavailable. Your word is kept; try again.','O serviço de salas está temporariamente indisponível. A tua palavra foi mantida; tenta novamente.']};
function message(where,e){$(where).textContent=errors[e]?tr(...errors[e]):e;if(where==='game-error')$('result-error').textContent=$(where).textContent;}
function stored(key){try{return sessionStorage.getItem(key);}catch{return null;}}
function save(key,value){try{value===null?sessionStorage.removeItem(key):sessionStorage.setItem(key,value);}catch{}}
// Launch animation, like the start of a game: the middle tile counts 3, 2, 1, then all five tiles flip into a
// friendly word that changes each time the app opens ("TODAY" when a daily streak is waiting).
const LAUNCH_WORDS=['hello','plays','games','words','duels','spell','clues','guess','smile','ready','happy','brain','lucky','charm','spark','quest','cheer','sunny','bloom','dream','merry','score','tiles','pairs'];
const launchStart=Date.now(),LAUNCH_MAX=2500,COUNT_STEP=220;let LAUNCH_MIN=1300;
function launchMemory(){try{return JSON.parse(localStorage.getItem('lexivanto-launch')||'{}');}catch{return {};}}
function rememberLaunch(patch){try{localStorage.setItem('lexivanto-launch',JSON.stringify({...launchMemory(),...patch}));}catch{}}
function startLaunch(){const box=$('launch'),tiles=Array.from($('launch-tiles')?.children||[]);if(!box||tiles.length!==5)return;const m=launchMemory(),d=new Date(),today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
 let word=m.streak>0&&m.dailyDone!==today&&m.last!=='today'?'today':'';
 if(!word){const pool=LAUNCH_WORDS.filter(w=>w!==m.last);word=pool[Math.floor(Math.random()*pool.length)];}
 rememberLaunch({last:word});
 // Each tile stays an empty tile until its own flip (60 ms apart), so the row never shows gaps.
 const reveal=(stagger)=>{box.classList.remove('count');box.classList.add('go');tiles.forEach((t,i)=>setTimeout(()=>{t.textContent=word[i].toUpperCase();t.className='tile exact flip';},stagger?i*60:0));};
 let still=false;try{still=matchMedia('(prefers-reduced-motion: reduce)').matches;}catch{}
 if(still){LAUNCH_MIN=600;reveal(false);}else{box.classList.add('count');const mid=tiles[2];['3','2','1'].forEach((n,k)=>setTimeout(()=>{mid.textContent=n;mid.className='tile present';void mid.offsetWidth;mid.classList.add('count-flip');},k*COUNT_STEP));setTimeout(()=>reveal(true),3*COUNT_STEP);}
 setTimeout(()=>endLaunch(true),LAUNCH_MAX);}
let launchEnded=false;
function endLaunch(fast){const box=$('launch');if(!box||launchEnded)return;launchEnded=true;setTimeout(()=>{box.classList.add('done');setTimeout(()=>{box.hidden=true;},300);},fast?0:Math.max(0,LAUNCH_MIN-(Date.now()-launchStart)));}
try{startLaunch();}catch{}
let token=stored('cw-player-token');if(!token){token=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join('');save('cw-player-token',token);}
// The match seat token is per tab; the daily word and its streak use a device id that survives new tabs and restarts.
let deviceId='';try{deviceId=localStorage.getItem('lexivanto-device')||'';if(!/^[a-f0-9]{64}$/.test(deviceId)){deviceId=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join('');localStorage.setItem('lexivanto-device',deviceId);}}catch{deviceId='';}
const bestOf=()=>state?.settings?.bestOf>1;
let introWas=false;
function signed(n){return (n>0?'+':n<0?'−':'±')+Math.abs(n);}
function stakesText(){const k=state?.stakes;if(!k)return '';return (k.placement?'Placement game · ':'')+'Win '+signed(k.win)+' · Draw '+signed(k.draw)+' · Lose '+signed(k.lose);}
function wordIntro(){if(!bestOf()||state.status!=='playing')return '';const left=Math.ceil((state.startsAt-Date.now()-offset)/1000);if(left<=0)return '';const last=state.words?.at(-1),n=state.words?.length||0;if(!last){const k=state.stakes;return k?(k.placement?'Placement · ':'')+'Win '+signed(k.win)+' · Lose '+signed(k.lose):state.unrated==='pair_cap'?'Not rated this time':'Get ready';}const who=last.winner===null?'Nobody':last.winner===state.me?'You':(state.players[1-state.me]?.name||'Opponent');return who+' won word '+n+': '+String(last.answer).toUpperCase();}
function nextMatch(){$('result').close();resultDismissed=true;Promise.resolve(returnToModes()).then(ok=>{if(ok!==false)startQueue('ranked');});}
// Support link (REDESIGN-PLAN.md section 8). Empty keeps it hidden; set it to the Ko-fi or similar page.
const SUPPORT_URL='https://ko-fi.com/elbully';
let installPrompt=null;
function isStandalone(){try{return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}catch{return false;}}
function isIos(){return /iphone|ipad|ipod/i.test(navigator.userAgent||'')||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
function pushSupported(){return typeof navigator!=='undefined'&&'serviceWorker' in navigator&&typeof PushManager!=='undefined'&&typeof Notification!=='undefined';}
function pushPrefs(){return {invites:!!preferences.push?.invites,reminders:!!preferences.push?.reminders};}
function savePushPrefs(p){preferences.push=p;try{localStorage.setItem('lexivanto-preferences',JSON.stringify(preferences));}catch{}}
function renderAppSection(){const p=pushPrefs(),installed=isStandalone();
 $('install-app').hidden=!installPrompt||installed;
 $('install-note').textContent=installed?'Lexivanto is installed on this device.':installPrompt?'Install Lexivanto to open it from your home screen like an app.':isIos()?'On iPhone or iPad: tap Share, then Add to Home Screen. Notifications on iPhone work only from the Home Screen app.':'You can install Lexivanto from your browser menu to open it like an app.';
 const blocked=!pushSupported(),denied=!blocked&&Notification.permission==='denied';
 for(const [id,on,extra] of [['notify-invites',p.invites,!signedAccount],['notify-reminder',p.reminders,false]]){const b=$(id);b.setAttribute('aria-checked',String(on));b.textContent=on?'On':'Off';b.disabled=busyPush||blocked||denied||extra;}
 $('notify-invites-note').textContent=signedAccount?'When a friend invites you while the game is closed.':'Invitations come from friends, so they need an account. The streak reminder works without one.';
 if(blocked)$('notify-status').textContent=isIos()&&!installed?'Add Lexivanto to your Home Screen to turn on notifications.':'This browser does not support notifications.';else if(denied)$('notify-status').textContent='Notifications are blocked for this site. Allow them in your browser settings to turn these on.';
 $('support-link').hidden=!SUPPORT_URL;if(SUPPORT_URL)$('support-link').href=SUPPORT_URL;}
let busyPush=false;
function keyBytes(s){const b=atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4));return Uint8Array.from(b,c=>c.charCodeAt(0));}
async function syncPush(next,askPermission){if(!pushSupported())return;busyPush=true;renderAppSection();$('notify-status').textContent='';try{const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(next.invites||next.reminders){if(askPermission&&Notification.permission!=='granted'&&await Notification.requestPermission()!=='granted'){$('notify-status').textContent='Notifications were not allowed, so nothing was turned on.';return;}if(!sub){const r=await fetch('/api/push/key',{headers:{authorization:'Bearer '+token}});const {publicKey}=await r.json();sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(publicKey)});}}if(!sub){savePushPrefs({invites:false,reminders:false});return;}let timeZone='UTC';try{timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';}catch{}const r=await fetch('/api/push/subscribe',{method:'POST',headers:{authorization:'Bearer '+token,...(deviceId?{'x-lexivanto-device':deviceId}:{}),'content-type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint,invites:next.invites,reminders:next.reminders,timeZone}),signal:AbortSignal.timeout(12000)});const data=await r.json();if(!r.ok)throw Error(data.error||'storage_unavailable');savePushPrefs({invites:data.invites,reminders:data.reminders});if(!data.invites&&!data.reminders)await sub.unsubscribe().catch(()=>{});else if(askPermission)$('notify-status').textContent='Saved. You can change this any time.';}catch(e){$('notify-status').textContent='Notifications could not be changed. Try again.';}finally{busyPush=false;renderAppSection();}}
const isDaily=()=>state?.settings?.mode==='daily';
// Turn-based friend games (Phase 6)
const isTurns=()=>state?.settings?.pace==='turns';
function timeLeft(ms){if(ms<=0)return 'Time is up';const h=Math.floor(ms/36e5),d=Math.floor(h/24);return d?d+' d '+(h%24)+' h left':h?h+' h left':Math.max(1,Math.ceil(ms/6e4))+' min left';}
async function turnsApi(path,body){const r=await fetch('/api/turns'+path,{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,...(body?{'content-type':'application/json'}:{})},signal:AbortSignal.timeout(12000),...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw Error('storage_unavailable');}if(!r.ok)throw Error(data.error||'storage_unavailable');return data;}
async function openTurns(c){if(busy)return;busy=true;try{remote=true;code=c;save('cw-room',c);revision=-1;draft='';lastBoard='';lastKeys='';resultDismissed=false;connectionOk=true;const data=await api();adopt(data);translate();}catch(e){remote=false;code='';save('cw-room',null);state=null;message('menu-error',e.message==='room_access'?'This game is on another account.':e.message);showStep('modes');}finally{busy=false;if(state)render();menuControls();}}
function refreshTurns(){if(!loaded||!signedAccount){$('turns-home').hidden=true;return;}turnsApi('').then(d=>{const list=$('turns-list');list.replaceChildren();for(const g of d.games){const li=document.createElement('li'),b=document.createElement('button');b.type='button';b.className=g.myTurn?'my-turn':'';const name=document.createElement('strong');name.textContent='vs '+g.opponent;const st=document.createElement('span');st.className='turn-state';st.textContent=g.status==='playing'?(g.myTurn?'Your turn':'Their turn'):g.result==='won'?'You won':g.result==='lost'?(g.mode==='coop'?'Not solved':'You lost'):'Draw';const sub=document.createElement('small');sub.textContent=(g.mode==='coop'?'Co-op':'Duel')+' · take turns';b.append(name,st,sub);b.setAttribute('aria-label','vs '+g.opponent+', '+sub.textContent+', '+st.textContent);b.onclick=()=>openTurns(g.code);li.append(b);list.append(li);}$('turns-home').hidden=!d.games.length;}).catch(()=>{});}
async function renderTurnsFriends(){const section=$('turns-section'),box=$('turns-friends');const fits=!!signedAccount&&['duel','coop'].includes(mode);section.hidden=!fits;if(!fits)return;box.replaceChildren();$('turns-error').textContent='';try{const r=await fetch('/api/friends',{headers:{authorization:'Bearer '+token},signal:AbortSignal.timeout(8000)});const data=await r.json();const list=(data.friends||[]).filter(f=>f.status==='accepted');if(!list.length){const p=document.createElement('p');p.className='flow-note';p.textContent='Add a friend in Friends to take turns with them.';box.append(p);return;}for(const f of list){const b=document.createElement('button');b.type='button';b.textContent='Start a '+(mode==='coop'?'Co-op game':'Duel')+' with '+f.name;b.onclick=()=>startTurns(f.tag);box.append(b);}}catch{$('turns-error').textContent='Your friends could not load. Try again.';}}
async function startTurns(tag){if(busy)return;busy=true;$('turns-error').textContent='';try{const data=await turnsApi('/start',{friend:tag,mode,attempts:Number($('attempts').value)});remote=true;code=data.code;save('cw-room',code);revision=-1;draft='';lastBoard='';resultDismissed=false;adopt(data);translate();}catch(e){$('turns-error').textContent=e.message==='too_many_games'?'You already have 20 games going. Finish one first.':e.message==='friend_required'?'You can only take turns with accepted friends.':e.message;}finally{busy=false;if(state)render();menuControls();}}

const EMOTE_LABELS={hello:'Hello',nice:'Nice guess',wow:'Wow',oops:'Oops',thanks:'Thanks',gg:'Good game'};
const COACH_TIPS=['Your first game: type any five-letter word and press Enter.','Read the clues: a square with a tick is the right letter in the right place, a circle is in the word somewhere else, a flat tile is not in the word.','Use every clue on the board to find the word first. Back shows every way to play, including the daily word.'];
let coachSeen=-1,coachOn=false,emoteSeen=[0,0];
function localDay(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function dailyState(d){return {settings:{mode:'daily',lang:'en',seconds:0,clockMode:'round',attempts:6},players:[{name:$('nickname').value.trim()||'You'},null],me:0,status:d.status,rows:d.guesses,boards:[[],[]],counts:[0,0],submitted:[false,false],solved:[d.solved?{tries:d.tries}:null,null],round:d.guesses.length+1,winner:d.status==='finished'?(d.solved?0:null):null,reason:d.status==='finished'?(d.solved?'solved':'attempts'):'',answer:d.answer||null,match:1,deadline:0,daily:d};}
async function dailyApi(path,body){const r=await fetch('/api/daily'+path,{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,...(deviceId?{'x-lexivanto-device':deviceId}:{}),...(body?{'content-type':'application/json'}:{})},signal:AbortSignal.timeout(12000),...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw Error('storage_unavailable');}if(!r.ok){const e=Error(data.error||'storage_unavailable');e.data=data;throw e;}return data;}
async function openDaily(){if(busy||!loaded)return;busy=true;menuControls();message('menu-error','');try{const d=await dailyApi('?day='+localDay());remote=false;local=null;code='';draft='';lastBoard='';lastKeys='';save('lexivanto-practice',null);resultDismissed=false;state=dailyState(d);}catch(e){message('menu-error',e.message);}finally{busy=false;menuControls();if(state)render();}}
async function submitDaily(){busy=true;try{const d=await dailyApi('/guess',{day:state.daily.day,word:draft});draft='';state=dailyState(d);}catch(e){if(e.message==='daily_finished'&&e.data?.guesses)state=dailyState(e.data);else if(e instanceof TypeError)message('game-error','You’re offline. Your word is kept; press Enter again when you’re back online.');else message('game-error',e.message);}finally{busy=false;render();}}
function refreshDaily(){if(!loaded)return;dailyApi('?day='+localDay()).then(d=>{rememberLaunch({streak:d.progress.streak,dailyDone:d.status==='finished'?d.day:null});const p=d.progress,streak=p.streak?' · '+p.streak+'-day streak':'';$('way-daily-meta').textContent=d.status==='finished'?(d.solved?'Solved in '+d.tries+'/6':'Not solved today')+streak+' · new word at midnight':'#'+d.number+streak+' · not rated';}).catch(()=>{});}
function shareText(){const d=state.daily,marks={exact:'🟦',present:'🟡',absent:'⬛'};return 'Lexivanto #'+d.number+' '+(d.solved?d.tries:'X')+'/6'+(d.progress?.streak>1?' · '+d.progress.streak+'-day streak':'')+'\n'+d.guesses.map(g=>g.colors.map(c=>marks[c]).join('')).join('\n')+'\nhttps://lexivanto.com';}
async function shareDaily(){const text=shareText();try{if(navigator.share){await navigator.share({text});return;}}catch(e){if(e?.name==='AbortError')return;}try{await navigator.clipboard.writeText(text);message('result-error','Result copied. Paste it anywhere.');}catch{message('result-error','Copy failed. Select and copy: '+text.replace(/\n/g,' '));}}
function distBars(dist,mine){const box=document.createElement('div');box.className='dist';box.setAttribute('role','img');const max=Math.max(1,...dist);dist.forEach((n,i)=>{const row=document.createElement('div');row.className='dist-row'+(i===mine?' mine':'');const label=document.createElement('span');label.textContent=i<6?String(i+1):'X';const bar=document.createElement('span');bar.className='dist-bar';bar.style.width=Math.max(8,Math.round(n/max*100))+'%';bar.textContent=n;row.append(label,bar);box.append(row);});box.setAttribute('aria-label','Guess spread: '+dist.map((n,i)=>(i<6?(i+1)+' guesses':'not solved')+' '+n).join(', '));return box;}
function renderDailyResult(){const d=state.daily,box=$('result-rating');box.replaceChildren();const wrap=document.createElement('div');wrap.className='daily-result';const h=document.createElement('h3');h.textContent='Today: '+d.today.total.toLocaleString('en')+(d.today.total===1?' player':' players');wrap.append(h,distBars(d.today.dist,d.solved?d.tries-1:6));const note=document.createElement('p');note.className='rating-note';if(d.friends?.length){const fh=document.createElement('h3');fh.textContent='Friends';const ul=document.createElement('ul');ul.className='daily-friends';for(const f of d.friends){const li=document.createElement('li');li.textContent=f.name+' · '+(f.solved?f.tries+'/6':'not solved');ul.append(li);}wrap.append(fh,ul);}else{note.textContent=d.friends?'None of your friends has finished today’s word yet.':'Sign in to compare with friends and keep your streak on every device.';wrap.append(note);}box.append(wrap);box.hidden=false;}
async function loadStats(){const lv=$('stats-level'),grid=$('stats-daily'),dist=$('stats-dist'),rt=$('stats-rating');try{const d=await dailyApi('/stats?day='+localDay());lv.replaceChildren();if(d.level){const t=document.createElement('strong');t.textContent='Level '+d.level.level;const sub=document.createElement('span');sub.className='muted';sub.textContent=' · '+d.level.into+' of '+d.level.need+' XP to level '+(d.level.level+1);const bar=document.createElement('div');bar.className='xp-track';const fill=document.createElement('span');fill.style.width=Math.round(d.level.into/d.level.need*100)+'%';bar.append(fill);lv.append(t,sub,bar);}else lv.textContent='Sign in to earn XP and levels.';grid.replaceChildren();const x=d.daily;for(const [k,v] of [['Played',x.played],['Solved',x.played?Math.round(x.won/x.played*100)+'%':'—'],['Streak',x.streak],['Best',x.best],['Freezes',x.freezes]]){const c=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;c.append(dt,dd);grid.append(c);}const bars=distBars(x.dist,-1);dist.replaceChildren(...bars.children);dist.setAttribute('aria-label','Daily word guess spread. '+bars.getAttribute('aria-label'));rt.textContent=d.history?.length>1?'Rating '+d.history[0].rating_after.toLocaleString('en')+' → '+d.history.at(-1).rating_after.toLocaleString('en')+' over your last '+d.history.length+' rated games.':d.rating?.rated_games?'Rating '+d.rating.rating.toLocaleString('en')+'.':'';}catch{lv.textContent='Stats could not load. Try again later.';}}
function renderEmotes(){if(!remote||!state){$('emote-button').hidden=true;$('emote-tray').hidden=true;return;}const other=1-state.me,muted=!!preferences.muteEmotes;$('emote-button').hidden=!state.players[other];if($('emote-button').hidden)$('emote-tray').hidden=true;$('emote-mute').textContent=muted?'Unmute reactions':'Mute reactions';$('emote-mute').setAttribute('aria-pressed',String(muted));const now=Date.now()+offset;[[state.me,'you-emote'],[other,'other-emote']].forEach(([seat,id])=>{const e=state.emotes?.[seat],show=!!e&&now-e.at<3500&&!(seat===other&&muted);$(id).hidden=!show;if(show)$(id).textContent=EMOTE_LABELS[e.id]||'';if(e&&e.at>emoteSeen[seat]){emoteSeen[seat]=e.at;if(seat===other&&!muted&&now-e.at<3500)$('announcement').textContent=(state.players[other]?.name||'Opponent')+': '+(EMOTE_LABELS[e.id]||'');}});}
async function sendEmote(id){$('emote-tray').hidden=true;$('emote-button').setAttribute('aria-expanded','false');try{adopt(await api('emote',{emote:id,match:state.match}));}catch(e){if(!['too_fast','too_many_emotes'].includes(e.message))message('game-error',e.message);}}
function renderCoach(){$('welcome').hidden=!coachOn||!!state||coachSeen>=0;const show=coachOn&&!!state&&state.status==='playing'&&!isDaily();let tip=-1;if(show){const n=shownRows().length;tip=n===0?0:n<=2?1:2;}const visible=show&&tip>coachSeen;$('coach').hidden=!visible;if(visible){$('coach-text').textContent=COACH_TIPS[tip];$('coach').dataset.tip=String(tip);}}
// First visit = nothing in permanent storage yet. Practice games are kept per tab (sessionStorage) so a reload resumes them.
function firstVisit(){try{if(localStorage.getItem('lexivanto-preferences')||localStorage.getItem('lexivanto-seen'))return false;localStorage.setItem('lexivanto-seen','1');return true;}catch{return false;}}
function restorePractice(){const raw=stored('lexivanto-practice');if(!raw)return false;try{const p=JSON.parse(raw);if(Date.now()-p.at>6*36e5||p.local?.status!=='playing'||!p.local.players?.[1])throw Error();local=p.local;remote=false;code='';mode=local.settings.mode;opponent='bot';state=view(local,0);botRound='';return true;}catch{save('lexivanto-practice',null);return false;}}
function matchKind(){if(isDaily())return{key:'daily',label:'DAILY WORD #'+state.daily.number,note:'Same word for everyone today. Not rated.'};if(!state)return{key:'practice',label:'PRACTICE · NOT RATED',note:'Practice games never change your rating.'};if(!remote)return{key:'practice',label:'PRACTICE · NOT RATED',note:'Practice games never change your rating.'};if(isTurns())return{key:'friend',label:'FRIEND GAME · TAKE TURNS',note:'Not rated. Play whenever you like; 3 days per move.'};if(!state.online)return{key:'friend',label:'FRIEND GAME · NOT RATED',note:'Friend games never change your rating.'};if(state.queue==='normal')return{key:'online',label:'NORMAL · NOT RATED',note:'Normal games never change your rating.'};if(state.queue==='ranked'&&state.unrated==='pair_cap')return{key:'online',label:'COMPETITIVE · NOT RATED',note:'Not rated: you have played 3 rated games with this player today.'};if(state.queue==='ranked'&&bestOf())return{key:'rated',label:'COMPETITIVE · RATED',note:stakesText()||'Rated: your rating changes with this result.'};const mine=state.players[state.me]?.tag,theirs=state.players[1-state.me]?.tag;if(mine&&theirs&&mine!==theirs)return{key:'rated',label:'COMPETITIVE · RATED',note:'Rated: your Duel rating changes with this result.'};return{key:'online',label:'ONLINE · NOT RATED',note:mine?'Not rated: your opponent is playing as a guest.':'Not rated: sign in to play rated Duels.'};}
function deepScreen(){return !!state||!!search||step!=='modes';}
function syncHistory(){try{if(deepScreen()&&!history.state?.lexivanto)history.pushState({lexivanto:1},'',location.href);}catch{}}
try{addEventListener('popstate',()=>{const open=[...document.querySelectorAll('dialog[open]')].at(-1);if(open)open.close();else if(deepScreen())back();setTimeout(syncHistory,0);});}catch{}
function track(event){try{if(!token)return;fetch('/api/event',{method:'POST',keepalive:true,headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({event})}).catch(()=>{});}catch{}}
function trackVisit(){try{const today=new Date().toISOString().slice(0,10);if(localStorage.getItem('lexivanto-visit')===today)return;localStorage.setItem('lexivanto-visit',today);track('visit');}catch{}}
const trackedMatches=new Set();function trackFinish(){if(!state||state.status!=='finished'||state.reason==='cancelled')return;const key=isDaily()?'daily:'+state.daily.day:(code||local?.created||'p')+':'+state.match;if(trackedMatches.has(key))return;trackedMatches.add(key);track(isDaily()?'daily_finished':!remote?'practice_finished':state.online?'online_finished':'friend_room_finished');}
function renderRating(rated,e,progress){const box=$('result-rating');box.replaceChildren();const n=x=>Number(x).toLocaleString('en');const add=(tag,cls,text)=>{const el=document.createElement(tag);el.className=cls;el.textContent=text;box.append(el);return el;};const pl=progress?.placement;if(rated&&e&&pl&&!pl.done){add('span','rating-label','Placement');add('strong','rating-line','Game '+pl.played+' of '+pl.of);add('span','rating-note','Your rating and tier appear after '+pl.of+' games.');}else if(rated&&e){if(progress?.placedNow)add('span','rating-promo','Placed in '+progress.tier);else if(progress?.promoted)add('span','rating-promo','Promoted to '+progress.tier);add('span','rating-label','Rating');const line=add('span','rating-line','');const from=document.createElement('span');from.className='rating-from';from.textContent=n(e.rating_before);const to=document.createElement('strong');to.className='rating-to';to.textContent=n(e.rating_after);line.append(from,' → ',to);const d=add('span','rating-delta '+(e.delta>0?'gain':e.delta<0?'loss':'even'),(e.delta>0?'+':e.delta<0?'−':'±')+Math.abs(e.delta));d.setAttribute('aria-label',(e.delta>=0?'Gained ':'Lost ')+Math.abs(e.delta)+' rating');if(progress?.tier&&!progress.placedNow&&!progress.promoted)add('span','rating-note',progress.tier);}else add('span','rating-delta unrated',progress?.unrated==='pair_cap'?'Not rated · 3 rated games with this player today':'Not rated');if(e?.xp)add('span','rating-xp','+'+e.xp+' XP');box.hidden=false;}
try{addEventListener('online',()=>{if(!resendWhenOnline)return;resendWhenOnline=false;setTimeout(()=>{if(state?.status==='playing'&&draft.length===5&&canType()){message('game-error','');submit();}},800);});}catch{}
function explainTie(){if(!state||state.status!=='finished'||state.settings.mode!=='duel'||state.reason!=='solved'||state.winner===null||state.winner===undefined)return;const solved=shownRows().filter(r=>r.colors?.length===5&&r.colors.every(c=>c==='exact'));if(new Set(solved.map(r=>r.player)).size<2)return;const other=state.players[1-state.me]?.name||'Your opponent';const line=state.winner===state.me?'You both solved it in the same round; you locked your guess first.':'You both solved it in the same round; '+other+' locked their guess first.';if(!$('result-detail').textContent.includes('same round'))$('result-detail').textContent+='\n'+line;}
function shakeDraft(){const row=$('draft-row');row.classList.remove('shake');void row.offsetWidth;row.classList.add('shake');}
function modeName(m=mode){return ({daily:'Daily word',duel:tr('Duel','Duelo'),race:tr('Race','Corrida'),coop:tr('Co-op','Cooperação'),swap:'Word swap'})[m];}
function config(forPlay=true){return settings({mode,lang,clockMode:mode==='duel'?'response':'round',difficulty:$('difficulty').value,seconds:forPlay&&opponent==='bot'?0:Number($('clock').value),sudden:false,attempts:Number($('attempts').value)});}
function onlineRules(){return onlineSettings(mode,lang,onlinePreferences[mode]);}
function onlineTiming(){$('online-description').textContent=(signedAccount?'Rated Duel · ':'Not rated as a guest · ')+clockText(onlineRules());}
function applyTheme(value){const theme=value==='light'?'light':'dark';preferences.theme=theme;document.documentElement.dataset.theme=theme;$('theme-button').textContent=theme==='dark'?tr('Light mode','Modo claro'):tr('Dark mode','Modo escuro');$('theme-button').setAttribute('aria-pressed',String(theme==='dark'));}
function clockText(s){if(!s.seconds)return tr('No time limit','Sem limite de tempo');if(s.mode==='duel'&&s.clockMode==='response')return tr(s.seconds+' s to reply',s.seconds+' s para responder');const unit=['race','swap'].includes(s.mode)?tr('match','partida'):s.mode==='coop'?tr('turn','turno'):tr('round','ronda');const time=s.seconds>=60&&['race','swap'].includes(s.mode)?(s.seconds/60)+' min':s.seconds+' s';return time+' / '+unit+(s.sudden?tr(' · after round 6',' · após a ronda 6'):'');}
function ruleText(s){if(s.mode==='daily')return 'One word for everyone today. Six guesses. Not rated.';if(s.mode==='swap')return 'Choose a five-letter word for each other. Both players finish. Fewer guesses wins; equal guesses are decided by solving time. No time limit. Not rated.';if(s.mode==='duel'&&s.clockMode==='response'&&!s.seconds)return tr('Both choose a word with no time limit. Lock your guess, then reveal both words together.','Ambos escolhem uma palavra sem limite de tempo. Confirma a tentativa e revelem as duas palavras em conjunto.');if(s.mode==='duel'&&s.clockMode==='response')return tr('Both choose a word. The first locked guess starts the other player’s response timer. Both guesses reveal after the reply. If you do not reply in time, your opponent wins.','Ambos escolhem uma palavra. A primeira confirmação inicia o tempo de resposta do outro jogador. As tentativas são reveladas após a resposta. Se não responderes a tempo, ganha o adversário.')+(s.seconds?'':tr(' This match has no time limit.',' Esta partida não tem limite de tempo.'));if(s.mode==='duel')return tr('Both players submit once per round. Both guesses reveal together. The first correct submission wins; equal server timestamps draw. No six-round limit.','Ambos enviam uma tentativa por ronda. As duas são reveladas em conjunto. Ganha a primeira resposta certa; se o servidor registar tempos iguais, há empate. Sem limite de seis rondas.');if(['race','swap'].includes(s.mode))return tr('Same word, separate boards. First correct guess wins. Play independently with unlimited guesses and no timer.','A mesma palavra, tabuleiros separados. Ganha quem usar menos tentativas; em caso de igualdade, decide o tempo. Quando um acerta, o outro ainda pode ganhar com menos tentativas.');return tr('Take turns on one shared board. Find the word together. ','Joguem à vez no mesmo tabuleiro. Descubram a palavra juntos. ')+(s.attempts?tr(`${s.attempts} total attempts.`,`${s.attempts} tentativas no total.`):tr('Unlimited attempts.','Tentativas sem limite.'))+(s.seconds?tr(' A timeout ends the team game.',' Se o tempo acabar, termina o jogo da equipa.'):'');}
function translate(){document.documentElement.lang=lang==='pt'?'pt-PT':'en';document.querySelectorAll('[data-en]').forEach(el=>el.textContent=el.dataset[lang==='pt'?'pt':'en']);$('language').value=lang;$('help').ariaLabel=tr('How to play','Como jogar');$('close-help').ariaLabel=tr('Close','Fechar');$('close-profile').ariaLabel=tr('Close profile','Fechar perfil');$('join-code').ariaLabel=tr('Room code','Código da sala');$('board').ariaLabel=tr('Word board','Tabuleiro de palavras');$('keyboard').ariaLabel=tr('Keyboard','Teclado');$('nickname').placeholder=tr('Your name','O teu nome');setup(false);applyTheme(preferences.theme);accountRender();if(state)render();else showStep(step,false);}
function setup(reset=true){$('choose-bot').hidden=mode==='swap';$('choose-online').hidden=mode!=='duel';$('search-bot').hidden=mode==='swap';const options=['race','swap'].includes(mode)?[0]:[0,15,30,60,120];if(reset){const prior=matchPreferences[mode]||{};$('clock').value=options.includes(prior.seconds)?prior.seconds:0;$('sudden').value=prior.sudden===false?'no':'yes';$('attempts').value=[0,6,10].includes(prior.attempts)?prior.attempts:6;$('difficulty').value=['easy','normal','expert'].includes(prior.difficulty)?prior.difficulty:'easy';}$('clock-buttons').replaceChildren();for(const sec of options){const button=document.createElement('button');button.textContent=sec===0?tr('No limit','Sem limite'):mode==='race'?`${sec/60} min`:`${sec} s`;button.dataset.clock=String(sec);button.onclick=()=>{$('clock').value=sec;updateSummary();remember();};$('clock-buttons').append(button);}$('clock-label').textContent=mode==='race'?tr('Match time','Tempo da partida'):mode==='coop'?tr('Time per turn','Tempo por turno'):tr('Time to reply','Tempo para responder');$('friend-settings').hidden=['race','swap'].includes(mode);$('attempt-field').hidden=mode!=='coop';$('sudden-field').hidden=true;onlineTiming();updateSummary();}
function difficultyName(value){return ({easy:tr('Easy','Fácil'),normal:tr('Medium','Médio'),expert:tr('Hard','Difícil')})[value]||tr('Easy','Fácil');}
function updateSummary(){const s=config(false);$('sudden-field').hidden=true;$('rules-summary').textContent=clockText(s)+(mode==='coop'?' · '+(s.attempts?tr(s.attempts+' attempts',s.attempts+' tentativas'):tr('Unlimited attempts','Tentativas sem limite')):'');document.querySelectorAll('[data-clock]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.clock)===s.seconds)));document.querySelectorAll('[data-setting]').forEach(el=>el.setAttribute('aria-pressed',String($(el.dataset.setting).value===el.dataset.value)));}
function menuControls(){const blocked=busy||cancelling||!loaded;document.querySelectorAll('[data-mode],[data-level],#choose-online,#choose-friend,#choose-bot,#create,#join').forEach(el=>el.disabled=blocked);$('profile-button').disabled=!!search||busy;$('back-button').hidden=!state&&!search&&step==='modes';$('menu-button').hidden=true;$('back-button').textContent='← Back';const backDestination=state?(state.status==='finished'?'Back to game modes':'Back · confirm leaving this match'):search?'Back to opponent choice · cancel search':['bot','friend'].includes(step)?'Back to opponent choice':'Back to game modes';$('back-button').setAttribute('aria-label',backDestination);$('back-button').title=backDestination;$('menu-button').textContent=state&&state.status!=='finished'?(remote?tr('Leave match','Sair da partida'):tr('End practice','Terminar treino')):search?tr('Cancel search','Cancelar procura'):tr('Game modes','Modos de jogo');$('search-bot').disabled=cancelling;$('cancel-search').textContent=cancelling?tr('Cancelling…','A cancelar…'):search&&!search.legacy?'Cancel search':tr('Cancel · Change opponent','Cancelar · Mudar adversário');$('search-bot').hidden=mode==='swap'||search?.queue==='ranked';$('back-button').disabled=busy||cancelling;$('menu-button').disabled=busy||cancelling;}
function showStep(next,focus=true){resultDismissed=false;if($('result').open)$('result').close();document.body.classList.remove('playing');step=next;setTimeout(syncHistory,0);if(next==='friend')setTimeout(renderTurnsFriends,0);$('join-section').hidden=step!=='invite';$('menu').hidden=false;$('game-layout').hidden=true;if(next==='modes'){intent=null;searchQueue=null;}if(document.body.dataset)document.body.dataset.step=next;for(const page of ['modes','games','competitive','opponent','bot','friend','search'])$('step-'+page).hidden=step==='invite'?!['opponent','friend'].includes(page):page!==step;$('opponent-options').hidden=step==='invite';$('online-settings').hidden=true;$('friend-create').hidden=step==='invite';$('friend-heading').hidden=step==='invite';$('opponent-heading').textContent=step==='invite'?tr('Join your friend','Junta-te ao teu amigo'):modeName()+tr(' · Play with…',' · Jogar com…');$('bot-heading').textContent=modeName()+tr(' · Choose a bot',' · Escolhe um bot');$('friend-heading').textContent=modeName()+tr(' · Invite a friend',' · Convida um amigo');$('online-description').textContent=(signedAccount?'Rated Duel · ':'Not rated as a guest · ')+clockText(onlineRules());$('guest-name-field').hidden=!!signedAccount;$('signed-name').hidden=!signedAccount;$('signed-name').textContent=tr('Playing as ','A jogar como ')+(signedAccount?.name||'');renderActivity();menuControls();if(focus){const heading=$(step==='modes'?'modes-heading':step==='games'?'games-heading':step==='competitive'?'competitive-heading':['opponent','invite'].includes(step)?'opponent-heading':step==='bot'?'bot-heading':step==='friend'?'friend-heading':'search-heading');heading.focus();}}
function chooseMode(value){if(busy||!loaded)return;remember();mode=value;setup();message('menu-error','');if(intent){chooseOpponent(intent);return;}showStep('opponent');}
function validName(){if(signedAccount)$('nickname').value=signedAccount.name;if(!$('nickname').value.trim()){const n=new Uint16Array(1);crypto.getRandomValues(n);$('nickname').value='Player '+String(1000+n[0]%9000);}remember();message('menu-error','');return true;}
function chooseOpponent(value){if(mode==='swap'&&value!=='friend')return;if(busy||!loaded||!validName())return;opponent=value;remember();if(value==='online'){startSearch();return;}showStep(value==='bot'?'bot':'friend');}
async function queueApi(action,body){const r=await fetch('/api/matchmaking/'+action,{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(12000)});let data;try{data=await r.json();}catch{throw Error('storage_unavailable');}if(!r.ok){const error=Error(data.error||'storage_unavailable');error.status=r.status;error.data=data;if(r.status===429)searchRetryAt=Date.now()+Math.max(1000,Math.min(300000,Number(r.headers.get('retry-after')||60)*1000));throw error;}return data;}
function startSearch(restored){if(search||busy)return;search=restored||{seconds:onlineRules().seconds,searchId:Array.from(crypto.getRandomValues(new Uint8Array(16))).map(x=>x.toString(16).padStart(2,'0')).join(''),mode,lang,name:$('nickname').value.trim(),queue:searchQueue||(signedAccount?'ranked':'normal'),legacy:!searchQueue,started:Date.now()};save('lexivanto-search',JSON.stringify(search));showStep('search');$('search-normal').hidden=true;$('search-detail').textContent=search.queue==='ranked'?'Competitive · rated · Best of 3 words · 45 s per guess':'Normal · not rated · '+modeName(search.mode)+' · '+clockText(onlineRules());$('search-heading').textContent=search.queue==='ranked'?'Finding a rated opponent…':'Finding a player…';searchPoll();}
async function searchPoll(){if(!search||searchBusy||cancelling||Date.now()<searchRetryAt||document.hidden)return;searchBusy=true;const current=search;try{const data=await queueApi('search',current);if(search!==current||cancelling)return;message('menu-error','');if(data.status==='searching'&&data.window!==undefined){current.window=data.window;current.rating=data.rating;}if(data.status==='matched'){search=null;save('lexivanto-search',null);remote=true;connectionOk=true;revision=-1;code=data.room.code;save('cw-room',code);draft='';adopt(data.room);translate();if(state.status==='waiting')await action('ready');}else if(data.status==='cancelled'){const from=current.legacy||!current.queue?'opponent':current.queue==='ranked'?'competitive':'modes';search=null;save('lexivanto-search',null);showStep(from);}}catch(e){if(search===current&&!cancelling&&['sign_in_required','competitive_locked','cooldown'].includes(e.message)){search=null;save('lexivanto-search',null);showStep('competitive');renderCompetitive();message('menu-error',e.message==='competitive_locked'?'Play '+Math.max(1,(e.data?.normalNeeded||5)-(e.data?.normalGames||0))+' more Normal games to unlock Competitive.':e.message==='cooldown'?'You left a recent Competitive match. You can search again in '+Math.max(1,Math.ceil(((e.data?.until||0)-Date.now())/60000))+' min.':'sign_in_required');}else if(search===current&&!cancelling&&e.message==='account_active'){search=null;save('lexivanto-search',null);showStep('opponent');message('menu-error','account_active');}else if(search===current&&!cancelling&&e.status===429)message('menu-error','Search paused briefly. It will retry automatically; you can still cancel.');else if(search===current&&!cancelling)message('menu-error',tr('Search connection interrupted. Retrying… You can cancel below.','A ligação foi interrompida. A tentar novamente… Podes cancelar abaixo.'));}finally{searchBusy=false;}}
async function cancelSearch(destination='opponent'){if(!search||cancelling)return;if(destination==='opponent'&&search.queue&&!search.legacy)destination=search.queue==='ranked'?'competitive':'modes';cancelling=true;const current=search;$('cancel-search').disabled=true;menuControls();try{const data=await queueApi('cancel',current);if(data.status==='matched'){const r=await fetch('/api/rooms/'+data.room.code+'/leave',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({match:data.room.match}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('storage_unavailable');}search=null;save('lexivanto-search',null);message('menu-error','');showStep(destination);}catch{message('menu-error',tr('Could not confirm cancellation. Try Cancel search again.','Não foi possível confirmar o cancelamento. Tenta cancelar novamente.'));}finally{cancelling=false;$('cancel-search').disabled=false;menuControls();}}
function back(){if(search){cancelSearch('opponent');return;}if(state){requestMenu();return;}if(busy)return;if(step==='games'||step==='competitive'){showStep('modes');return;}if(['bot','friend'].includes(step)&&intent){message('menu-error','');showStep('games');return;}if(step==='invite')history.replaceState(null,'',location.pathname);message('menu-error','');showStep(['bot','friend'].includes(step)?'opponent':'modes');}
async function api(action='',body){const response=await fetch(action==='create'?'/api/rooms':`/api/rooms/${code}${action?'/'+action:''}`,{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,...(body?{'content-type':'application/json'}:{})},signal:AbortSignal.timeout(12000),...(body?{body:JSON.stringify({...(['guess','ready','leave','rematch','settings','choose-word','give-up'].includes(action)?{match:state?.match}:{}),...body})}:{})});let data;try{data=await response.json();}catch{throw Error('storage_unavailable');}if(!response.ok){if(response.status===429)roomRetryAt=Date.now()+Math.max(1000,Math.min(300000,Number(response.headers.get('retry-after')||60)*1000));if(data.error==='stale_match'&&data.room)adopt(data.room);const error=Error(data.error||'storage_unavailable');error.status=response.status;throw error;}return data;}
function adopt(data){if(data.code&&data.code!==code){$('invitation-link').value='';$('invite-sent').textContent='';}if(data.settings.lang!=='en')throw Error('This version supports English games only. Please start a new game.');if(remote&&data.revision!==undefined&&data.revision<revision)return;revision=data.revision??revision;offset=data.now-Date.now();state=data;code=data.code||code;lang=data.settings.lang;$('language').value=lang;render();}
function chooseAnswer(s,old){const list=dictionaries[s.lang].answers.filter(x=>x!==old);return list[Math.floor(Math.random()*list.length)];}
async function create(){if(busy||!validName())return;remember();busy=true;menuControls();$('create').disabled=true;message('menu-error','');try{const s=config();draft='';lastBoard='';revision=-1;$('invite-sent').textContent='';$('copy-link').textContent='Copy invitation link';if(opponent==='bot'){remote=false;code='';save('cw-room',null);local=makeRoom(s,$('nickname').value.trim()||tr('You','Tu'),'local',chooseAnswer(s));local.players[1]={name:'Milo',auth:'bot',ready:true};track('practice_started');state=view(local,0);render();await matchIntroduction();begin(local,Date.now());state=view(local,0);offset=0;botRound='';render();}else{remote=true;const data=await api('create',{settings:s,name:$('nickname').value});code=data.code;save('cw-room',code);adopt(data);}translate();$('board').focus();}catch(e){remote=false;message('menu-error',e.message);}finally{busy=false;$('create').disabled=false;if(state)render();menuControls();}}
async function joinRoom(value){if(busy||!validName())return;remember();let input=value.trim();try{if(input.includes('://'))input=new URL(input).searchParams.get('room')||'';}catch{}const room=input.replace(/\s/g,'').toUpperCase();if(!/^[A-F0-9]{12}$/.test(room)){message('menu-error',tr('Enter the 12-character room code.','Introduz o código de 12 caracteres.'));return;}busy=true;menuControls();$('join').disabled=true;try{remote=true;code=room;revision=-1;const info=await api('info');if(info.settings.lang!=='en')throw Error('This version supports English games only. Please create a new room.');const data=await api('join',{name:$('nickname').value});draft='';save('cw-room',code);adopt(data);translate();history.replaceState(null,'',location.pathname);}catch(e){remote=false;code='';message('menu-error',e.message);}finally{busy=false;$('join').disabled=false;if(state)render();menuControls();}}
function canType(){if(isDaily())return state.status==='playing'&&!busy;if(bestOf()&&state.status==='playing'&&state.startsAt>Date.now()+offset)return false;if(state?.settings.mode==='swap'){return state.status==='playing'&&!busy&&(state.started?!state.solved[state.me]&&!state.gaveUp[state.me]:!state.wordChosen[state.me]);}if(!state||state.status!=='playing'||busy)return false;if(state.settings.mode==='duel')return !state.submitted[state.me];if(state.settings.mode==='coop')return state.turn===state.me;return !state.solved[state.me];}
// Reveal feedback has priority over the next round's empty/covered rows.
function keepLatestResultVisible(scroll,board,count,mode){
 if(!count){scroll.scrollTop=0;return;}
 const first=board.children[Math.max(0,count-(mode==='duel'?2:1))],last=board.children[count-1];
 if(!first||!last)return;
 const viewport=scroll.getBoundingClientRect(),top=first.getBoundingClientRect().top-viewport.top-8,bottom=last.getBoundingClientRect().bottom-viewport.bottom+8;
 if(top<0)scroll.scrollTop+=top;
 else if(bottom>0)scroll.scrollTop+=Math.min(top,bottom);
}
function shownRows(){return ['race','swap'].includes(state.settings.mode)?state.boards[state.me]:state.rows;}
