function wordRow(row,p){const line=document.createElement('div');line.className='guess-row'+(row.pending?' pending':'')+(row.covered?' covered':'');if(row.covered)line.setAttribute('aria-label',(state.players[row.player]?.name||'Player')+' locked a word. Revealed when both players submit.');if(row.player!==undefined){const owner=document.createElement('span');const name=state.players[row.player]?.name||'Player',parts=name.trim().split(/\s+/u);owner.className='row-owner '+(row.player===p?'owner-you':'owner-peer');owner.textContent=(Array.from(parts[0])[0]||'?')+(parts.length>1?(Array.from(parts.at(-1))[0]||''):'');owner.textContent=owner.textContent.toUpperCase();owner.title=name+(row.player===p?' (you)':'');owner.setAttribute('aria-label',owner.title+' — guess');line.append(owner);}for(let i=0;i<5;i++){const tile=document.createElement('span'),c=row.colors?.[i];tile.className='tile '+(c||(row.word[i]?'filled':''));tile.textContent=(row.word[i]||'').toUpperCase();tile.ariaLabel=row.covered?'Covered letter':tile.textContent?(tile.textContent+', '+(c?tr({exact:'correct position',present:'wrong position',absent:'absent'}[c],{exact:'posição certa',present:'posição errada',absent:'ausente'}[c]):tr('not revealed','por revelar'))):tr('Empty','Vazio');if(c){const symbol=document.createElement('span');symbol.className='symbol';symbol.ariaHidden='true';symbol.textContent='';tile.append(symbol);}line.append(tile);}return line;}
