async function submit(){if(!canType())return;if(remote&&Date.now()<roomRetryAt){message('game-error','Please wait '+Math.ceil((roomRetryAt-Date.now())/1000)+' seconds before submitting. Your word is kept.');return;}if(draft.length!==5){message('game-error','five_letters');feedback.play('error');shakeDraft();return;}if(!dictionaries[state.settings.lang].set.has(draft)){message('game-error','unknown_word');feedback.play('error');shakeDraft();return;}if(isDaily()){submitDaily();return;}busy=true;try{if(remote){const data=await api(state.settings.mode==='swap'&&!state.started?'choose-word':'guess',{word:draft});draft='';adopt(data);}else{guess(local,0,draft,dictionaries[local.settings.lang].set,Date.now());draft='';state=view(local,0);}}catch(e){if(remote&&(e instanceof TypeError||/fetch|network/i.test(e.message||''))){resendWhenOnline=true;message('game-error','You’re offline. Your word is kept and will be sent when the connection returns.');}else message('game-error',e.message);}finally{busy=false;render();}}
