function requestMenu(){if(busy)return;$('resign-game').hidden=true;if(isTurns()&&state.status==='playing'){$('leave-title').textContent='Leave this game for now?';$('leave-detail').textContent='The game stays open, and you will get a notification when it is your move. You have 3 days per move.';$('confirm-leave').textContent='Back to Play';$('cancel-leave').textContent='Keep playing';$('resign-game').hidden=false;$('leave-dialog').showModal();return;}if(isDaily()||isTurns()){menu();return;}if(search){cancelSearch('modes');return;}if(!state||state.status==='finished'){returnToModes();return;}const practice=!remote,waiting=state.status==='waiting';$('leave-title').textContent=practice?tr('End practice?','Terminar treino?'):waiting?tr('Leave this room?','Sair desta sala?'):tr('Leave this match?','Sair desta partida?');$('leave-detail').textContent=practice?tr('This practice ends. You’ll return to the game modes.','O treino termina. Voltas aos três modos de jogo.'):waiting?tr('You’ll leave the room and return to game modes.','Vais sair da sala e voltar aos modos de jogo.'):state.settings.mode==='coop'?tr('This ends the team game for both players. You’ll return to game modes.','O jogo termina para ambos. Voltas aos modos de jogo.'):tr('Your opponent wins if you leave now. You’ll return to game modes.','O adversário ganha se saíres agora. Voltas aos modos de jogo.');$('confirm-leave').textContent=practice?tr('End practice','Terminar treino'):tr('Leave match','Sair da partida');if(bestOf()&&state.queue==='ranked'&&!waiting){const early=state.word===1&&!state.rows.length&&!state.submitted.some(Boolean),k=state.stakes;$('leave-detail').textContent=early?'The match will not count, but leaving a Competitive match means a short wait before your next search.':'Leaving counts as a loss'+(k?' ('+signed(k.lose)+' rating)':'')+' and means a short wait before your next Competitive search.';$('confirm-leave').textContent=!early&&k?'Leave · '+signed(k.lose)+' rating':'Leave match';}$('cancel-leave').textContent=waiting?tr('Stay in room','Ficar na sala'):tr('Keep playing','Continuar a jogar');$('leave-dialog').showModal();}
async function confirmLeave(resign=false){if(busy)return;if(isTurns()&&!resign){$('leave-dialog').close();menu();return;}busy=true;try{if(remote)await api('leave',{});else if(local)leave(local,0);$('leave-dialog').close();busy=false;menu();}catch(e){$('leave-dialog').close();if(['room_expired','room_access'].includes(e.message)){busy=false;menu();}else message('game-error',e.message);}finally{busy=false;}}
function formatSolveTime(ms){const sec=Math.floor(ms/1000);return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')+'.'+String(ms%1000).padStart(3,'0');}
function formatResultTime(ms){const sec=Math.floor(ms/1000);return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')+'.'+Math.floor((ms%1000)/100);}
function tickClock(){if(!state)return;if(remote)renderEmotes();if(isTurns()){const left=state.status==='playing'&&state.moveBy?state.moveBy-Date.now()-offset:null;$('timer').textContent=left===null?(state.status==='finished'?'Finished':'Take turns'):timeLeft(left);$('timer').classList.remove('urgent');$('timer').ariaLabel=left===null?$('timer').textContent:'Move within '+timeLeft(left).replace(' left','');$('time-fill').style.width='0%';return;}if(bestOf()&&state.status==='playing'){const pre=state.startsAt>Date.now()+offset;if(pre||introWas)$('turn-label').textContent=statusText();if(introWas&&!pre){introWas=false;render();return;}introWas=pre;if(pre){$('timer').textContent='Starts in '+Math.ceil((state.startsAt-Date.now()-offset)/1000);$('timer').classList.remove('urgent');$('time-fill').style.width='100%';return;}}if(state.settings.mode==='swap'){const ms=state.solved[state.me]?.at??(state.started?Math.max(0,Date.now()+offset-state.started):0);$('timer').textContent=state.gaveUp?.[state.me]?'Unsolved':state.started?formatSolveTime(ms):'Choose a word';$('timer').ariaLabel='Solving time '+$('timer').textContent;$('time-fill').style.width='0%';return;}const left=state.deadline?Math.max(0,Math.ceil((state.deadline-Date.now()-offset)/1000)):null;const response=state.settings.mode==='duel'&&state.settings.clockMode==='response';$('timer').textContent=state.status==='finished'?tr('Finished','Terminou'):left===null?(response&&state.settings.seconds?tr('Clock starts on lock','Relógio após confirmação'):tr('No clock','Sem relógio')):Math.floor(left/60)+':'+String(left%60).padStart(2,'0');$('timer').classList.toggle('counting',left!==null);$('timer').classList.toggle('urgent',left!==null&&left<=10);$('timer').ariaLabel=left===null?$('timer').textContent:tr(left+' seconds remaining',left+' segundos restantes');$('time-fill').style.width=left===null?'0%':Math.min(100,left/state.settings.seconds*100)+'%';$('time-fill').style.background=left!==null&&left<=10?'var(--danger)':'var(--blue)';}
async function poll(){if(!remote||!code||polling||busy||document.hidden||Date.now()<roomRetryAt)return;polling=true;const active=code;try{const data=await api();if(remote&&code===active){connectionOk=true;adopt(data);}}catch(e){if(remote&&code===active){if(e.status!==429)connectionOk=false;if(['room_expired','room_access'].includes(e.message))message('game-error',e.message);render();}}finally{polling=false;}}
function tick(){tickClock();if(search){const seconds=Math.max(0,Math.floor((Date.now()-search.started)/1000));$('search-elapsed').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(search.queue==='ranked'){$('search-wait').textContent=seconds>=60?'Few Competitive players are online. Keep waiting, or play Normal now.':search.window?'Looking for players within '+search.window+' of your rating ('+Number(search.rating||1000).toLocaleString('en')+').':'Looking for players near your rating.';$('search-normal').hidden=seconds<60;}else $('search-wait').textContent=seconds<20?tr('Waiting for another player…','À espera de outro jogador…'):tr('Still searching. Another player must choose the same mode and language.','Ainda à procura. Outro jogador tem de escolher o mesmo modo e língua.');}if(remote||!local||local.status!=='playing')return;const now=Date.now();if(expire(local,now)){state=view(local,0);render();return;}const stamp=local.match+'-'+local.round+'-'+local.boards[1].length;if(stamp!==botRound){botRound=stamp;botDue=now+botDelay(local.settings.difficulty);}const botTurn=local.settings.mode==='duel'?!local.pending[1]:local.settings.mode==='coop'?local.turn===1:!local.solved[1];if(botTurn&&now>=botDue){const word=botWord(local,1,dictionaries[local.settings.lang].botWords||dictionaries[local.settings.lang].allowed);if(word){try{guess(local,1,word,dictionaries[local.settings.lang].set,now);}catch{botDue=now+2000;}state=view(local,0);render();}}}

