setInterval(refreshActivity,20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshActivity();});
const friends=setupFriends({onAppearance:data=>{if(!$('avatar-editor').hidden)return;const i=characterIds.indexOf(data.avatar);if(i>=0)preferences.character=i;if(avatarColours.includes(data.colour))preferences.avatarColour=data.colour;renderPersonality();$('avatar-save-status').textContent='Saved to your account. New games use this avatar.';},onUpdated:()=>{if($('player-dialog').open)renderPlayerCard();},onUsername:()=>accountRender.refresh?.(),onNotice:()=>feedback.play('invite'),inMatch:()=>state?.status==='playing',currentRoom:()=>remote&&state&&!state.online?code:'',onJoin:async room=>{if(state||search||busy)throw Error('Finish your match or search first.');await joinRoom(room);if(!remote||!state)throw Error($('menu-error').textContent||'Could not join this game.');if(state.status==='waiting'&&!state.players[state.me]?.ready)await action('ready');},signedIn:()=>!!signedAccount,isAvailable:()=>!state&&!search&&!busy,canInvite:()=>!search&&!busy&&(!state||(remote&&!state.online&&state.status==='waiting'&&state.me===0&&!state.players[1])),seatToken:()=>token,currentMode:()=>state?.settings.mode||mode,onSent:name=>{$('invite-sent').textContent='Invitation sent to '+name+'. Waiting for them to join.';},onChallenge:async(tag,chosenMode)=>{if(remote&&state?.status==='waiting'&&!state.online&&!state.players[1]&&state.me===0)return code;if(state||search||busy)throw Error('Finish your match or search first.');if(mode!==chosenMode){mode=chosenMode;setup();}opponent='friend';await create();if(!remote||!code)throw Error($('menu-error').textContent||'Could not create the challenge.');return code;}});
async function boot(){lang='en';setTimeout(trackVisit,3000);preferences.lang='en';if(typeof preferences.name==='string'&&!['Player','Jogador'].includes(preferences.name))$('nickname').value=preferences.name.slice(0,24);busy=true;setup();translate();accountRender=setupAccount({language:()=>lang,onName:()=>{},onChange:user=>{const changed=signedAccount!==user;signedAccount=user;document.body.classList.toggle('guest',!user);if(changed)setTimeout(refreshTurns,0);if(changed||!user)friends.reset();if(user)friends.refresh();renderPersonality();if(user&&!state&&!search&&!busy){$('nickname').value=user.name;remember();}if(!state)showStep(step,false);}});try{for(const l of ['en']){const r=await fetch('words-'+l+'.json');if(!r.ok)throw Error();dictionaries[l]=await r.json();dictionaries[l].set=new Set(dictionaries[l].allowed);}loaded=true;const invite=new URLSearchParams(location.search).get('room');if(invite){
if(stored('lexivanto-search')){const old=JSON.parse(stored('lexivanto-search'));const cancelled=await queueApi('cancel',old);if(cancelled.status==='matched'){const r=await fetch('/api/rooms/'+cancelled.room.code+'/leave',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({match:cancelled.room.match}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();}save('lexivanto-search',null);}
if(stored('cw-room')){remote=true;code=stored('cw-room');try{const existing=await api();if(['playing','waiting'].includes(existing.status)){adopt(existing);translate();message('game-error',tr('Leave this match before opening another invitation.','Sai desta partida antes de abrir outro convite.'));return;}}catch{}remote=false;code='';save('cw-room',null);}
$('join-code').value=invite;opponent='friend';if(firstVisit())coachOn=true;showStep('invite',false);
try{const r=await fetch('/api/rooms/'+encodeURIComponent(invite.toUpperCase())+'/info',{headers:{authorization:'Bearer '+token}});const info=await r.json();if(!r.ok)throw Error(info.error||'room_expired');if(!info.available)throw Error('room_full');if(info.settings.lang!=='en')throw Error('This invitation uses a language that is currently unavailable. Create an English game instead.');mode=info.settings.mode;lang='en';translate();message('menu-error','');$('opponent-activity').textContent='Your friend chose '+modeName()+' · '+clockText(info.settings)+' · not rated';}catch(e){message('menu-error',e.message);}
}else if(stored('cw-room')){remote=true;code=stored('cw-room');try{const data=await api();connectionOk=true;adopt(data);translate();}catch{remote=false;code='';save('cw-room',null);message('menu-error',tr('Previous room unavailable. Start a new game.','A sala anterior está indisponível. Começa outra partida.'));}}else if(stored('lexivanto-search')){try{const prior=JSON.parse(stored('lexivanto-search'));if(prior.lang!=='en'){save('lexivanto-search',null);const retired=await queueApi('cancel',prior);if(retired.status==='matched'){await fetch('/api/rooms/'+retired.room.code+'/leave',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({match:retired.room.match}),signal:AbortSignal.timeout(12000)});}}if(prior.lang==='en'&&/^[a-f0-9]{32}$/.test(prior.searchId)&&prior.mode==='duel'){mode=prior.mode;onlinePreferences[mode]=prior.seconds;lang='en';busy=false;startSearch(prior);}}catch{save('lexivanto-search',null);}}else if(restorePractice()){}else if(firstVisit()){coachOn=true;coachSeen=-1;renderCoach();}}catch{loaded=false;message('menu-error',tr('Could not load the game. Try again.','Não foi possível carregar o jogo. Tenta novamente.'));$('retry-load').hidden=false;}finally{busy=false;if(signedAccount&&!state&&!search)$('nickname').value=signedAccount.name;menuControls();if(!state){refreshDaily();refreshTurns();}try{if(typeof navigator!=='undefined'&&'serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){navigator.serviceWorker.register('/sw.js').catch(()=>{});const p=pushPrefs();if(p.invites||p.reminders)setTimeout(()=>syncPush(p,false),4000);}}catch{}const link=new URLSearchParams(location.search);endLaunch(['game','daily','inbox','room'].some(k=>link.has(k)));if(!search&&/^[A-F0-9]{12}$/.test(link.get('game')||''))setTimeout(()=>openTurns(link.get('game')),0);else if(!state&&!search&&link.get('daily')==='1')setTimeout(openDaily,0);else if(!state&&!search&&link.get('inbox')==='1')setTimeout(()=>$('tab-inbox').click(),300);if(link.has('daily')||link.has('inbox')||link.has('source')||link.has('game'))history.replaceState(null,'',location.pathname);if(state){render();if(state.online&&state.match===1&&state.status==='waiting'&&!state.players[state.me].ready)action('ready');}}}boot().then(refreshActivity);

let roomDraft=null;
function renderRoomSettings(){for(const m of ["duel","race","coop","swap"])$("room-mode-"+m).setAttribute("aria-pressed",String(roomDraft.mode===m));$("room-clock-options").hidden=["race","swap"].includes(roomDraft.mode);$("room-settings-note").textContent=roomDraft.mode==="swap"?"Choose each other’s word. Both finish; fewer guesses wins, then time.":roomDraft.mode==="race"?"First to solve wins. Unlimited guesses. No timer.":"Both players will confirm they are ready before the next game starts.";document.querySelectorAll("[data-room-clock]").forEach(b=>b.setAttribute("aria-pressed",String(Number(b.dataset.roomClock)===roomDraft.seconds)));}
function openRoomSettings(){if(busy||!state||state.online||state.me!==0||!['waiting','finished'].includes(state.status)||state.players.some(x=>x?.departed))return;roomDraft={...state.settings};if($("result").open)$("result").close();resultDismissed=true;$("room-settings-error").textContent="";renderRoomSettings();$("room-settings-dialog").showModal();}
$("lobby-settings").onclick=openRoomSettings;$("lobby-friends").onclick=()=>friends.open();$("close-room-settings").onclick=()=>$("room-settings-dialog").close();for(const m of ["duel","race","coop","swap"])$("room-mode-"+m).onclick=()=>{roomDraft.mode=m;roomDraft.seconds=0;roomDraft.attempts=6;renderRoomSettings();};document.querySelectorAll("[data-room-clock]").forEach(b=>b.onclick=()=>{roomDraft.seconds=Number(b.dataset.roomClock);renderRoomSettings();});$("save-room-settings").onclick=async()=>{if(busy)return;busy=true;$("save-room-settings").disabled=true;try{adopt(await api("settings",{settings:roomDraft}));$("room-settings-dialog").close();}catch(e){$("room-settings-error").textContent=errors[e.message]?.[0]||e.message;}finally{busy=false;$("save-room-settings").disabled=false;render();}};

function renderPlayerCard(){if(!state)return;const peer=state.players[1-state.me],tag=peer?.tag,relation=tag?friends.playerStatus(tag):null;$('player-card-name').textContent=peer?.name||'Player';$('player-card-detail').textContent=!remote?'Practice opponent':!tag?'Guest player. Friend requests are available for signed-in players.':relation?.status==='blocked'?'Player blocked. Manage blocked players in Friends.':relation?.status==='accepted'?'Already friends':relation?.status==='pending'?(relation.incoming?'Sent you a friend request':'Friend request sent'):'Add this player to play together again.';$('player-card-block').hidden=!signedAccount||!tag||relation?.status==='blocked';$('player-card-report').hidden=!remote;$('player-card-report').href='/contact.html?kind=abuse'+(tag?'&player='+encodeURIComponent(tag):'')+(code?'&room='+encodeURIComponent(code):'');$('player-card-add').hidden=!tag||relation?.status==='blocked'||relation?.status==='accepted'||(relation?.status==='pending'&&!relation.incoming);$('player-card-add').textContent=!signedAccount?'Sign in to add friend':relation?.incoming?'Accept request':'Add friend';}
$('opponent-avatar').onclick=()=>{renderPlayerCard();$('player-card-status').textContent='';$('player-dialog').showModal();friends.refresh();};
$('close-player-card').onclick=()=>$('player-dialog').close();
$('player-dialog').addEventListener('close',()=>{if(state)$('opponent-avatar').focus();});
$('player-card-add').onclick=async()=>{if(!signedAccount){$('player-dialog').close();$('profile-button').click();return;}const tag=state?.players[1-state.me]?.tag;if(!tag)return;$('player-card-add').disabled=true;try{await friends.addPlayer(tag);renderPlayerCard();$('player-card-status').textContent='Done. You can manage this request in Friends.';}catch(error){$('player-card-status').textContent=error.message;}finally{$('player-card-add').disabled=false;}};

$('player-card-block').onclick=async()=>{const tag=state?.players[1-state.me]?.tag;if(!tag||!signedAccount)return;$('player-card-block').disabled=true;try{await friends.blockPlayer(tag);renderPlayerCard();$('player-card-status').textContent='Player blocked. This match stays open; use Back if you want to leave.';}catch(error){$('player-card-status').textContent=error.message;}finally{$('player-card-block').disabled=false;}};

